    vec3 sss = vec3(0.0, 0.8, 0.5) * (0.5 + 0.5 * sin(pos.y * 5.0 + time * 2.0));
    col = sss * 0.5 + diff * irid * 0.9 + spec * vec3(1.0) + rim * vec3(0.2, 1.0, 0.7);
